/* ---------------------------------------------------------------
   HELPERS
----------------------------------------------------------------*/
function formatStatus(status?: string | null) {
  if (!status) return "Unknown";

  switch (status.toLowerCase()) {
    case "completed":
      return "Delivered";

    case "accepted":
      return "Accepted";

    case "declined":
      return "Declined";

    case "outreach_pending":
      return "Outreach Pending";

    case "cancelled":
      return "Cancelled";

    default:
      return status.replaceAll("_", " ");
  }
}

function isCompleted(status?: string | null) {
  return (
    status?.toLowerCase() === "completed" ||
    status?.toLowerCase() === "delivered"
  );
}

function isAccepted(status?: string | null) {
  return status?.toLowerCase() === "accepted";
}

function getDestination(assignment: Assignment) {
  return (
    assignment.delivery_organization ||
    "Community destination"
  );
}

function getLocation(assignment: Assignment) {
  const city =
    assignment.pickup_city ||
    assignment.delivery_city ||
    "San Jose";

  return city;
}

function formatTime(timestamp?: string | null) {
  if (!timestamp) return "--:--";

  try {
    return new Date(timestamp).toLocaleTimeString(
      "en-US",
      {
        hour: "2-digit",
        minute: "2-digit",
        hour12: false,
      }
    );
  } catch {
    return "--:--";
  }
}

/* ---------------------------------------------------------------
   UI COMPONENTS
----------------------------------------------------------------*/
function Punch({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <div
      className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full"
      style={{
        background: C.canvas,
        boxShadow:
          "inset 0 0 0 1px rgba(0,0,0,0.35)",
      }}
    >
      {children}
    </div>
  );
}

function Stamp({
  status,
}: {
  status: string;
}) {
  const delivered =
    status.toLowerCase() === "delivered";

  const accepted =
    status.toLowerCase() === "accepted";

  const color = delivered
    ? C.green
    : accepted
      ? C.green
      : C.orange;

  return (
    <span
      className="inline-block -rotate-3 rounded-sm px-2.5 py-1 text-[9px] font-bold uppercase tracking-[0.14em]"
      style={{
        color,
        border: `1.5px dashed ${color}`,
        fontFamily: mono.fontFamily,
      }}
    >
      {status}
    </span>
  );
}

